UPDATE ar_ling_root_asl SET statement_ar = 'فأمّا المختص بالنفي فلاستغراق جنس الناطقين، ويتناول القليل والكثير على طريق الاجتماع والافتراق، نحو: ما في الدار أحد', statement_en = 'in denial, aḥad takes in all people, few or many', block_id = 'blk_mfr_679cb9db490ab5f6', page_ref = 66, note_md = 'Marker: head sense. Corrected: old quote «وأصله: وحد» is form history (hamza from wāw); opening line used, thin. Was: «أصله: وحد». Strengthened 2026-10-07: Was the cut opening «أَحَدٌ يستعمل على ضربين:» (blk_mfr_f02ffa6cfd2bdcd1). He also says «وأصله: وحد» (blk_mfr_d89fbca597767d41), as Ibn Fāris. Was: «أَحَدٌ يستعمل على ضربين:».', updated_at = datetime('now')
