UPDATE ar_ling_root_asl SET statement_ar = 'والحارصة: الشَّجَّة الَّتِي تحرص الْجلد أَي تقشره', statement_en = 'ḥāriṣa: a head wound that peels the skin', block_id = 'blk_jam_542910bc7ee685a7', page_ref = 477, note_md = 'Marker: head sense. Corrected: old quote was about حصر (mis-attributed); head gives no gloss, only «known». Was: «أصل الْحصْر الضّيق وَمِنْه الْحصْر: احتباس النجو كِنَايَة عَن ضيق مخرج ذِي الْبَ». Strengthened 2026-10-07: Thin head: «الْحِرْص: مَعْرُوف» (blk_jam_eea5fbe23a77d285) gives no gloss; his one glossed sense is peeling, which matches Ibn Fāris''s first aṣl (الشقّ) and al-Rāghib''s «أصل». Was: «الْحِرْص: مَعْرُوف. وَيُقَال: حرص يحرص حرصا».', updated_at = datetime('now')
