UPDATE ar_ling_root_asl SET note_md = 'Marker: head word. Corrected: current quote is Abū ʿAmr on the name عبشمس; head gives the noun only. Was: «أصله عب شمس، أي حب شمس، وهو ضوؤها، والعين مبدلة من الحاء كما قال في عب قر، وهو ا». Thin in this book: the sun is only named, never glossed. His glossed senses are «شَمَسَ يَوْمُنا… إذا كان ذا شَمْسٍ» and «شَمَسَ الفرسُ… أي منع ظهره» (blk_sih_36faaba13888a667); the sun is kept as his head word.', updated_at = datetime('now')
