UPDATE ar_ling_root_asl SET note_md = 'Marker: أصل (Ibn Fāris head sentence). Primary: most books head with hanging / clinging (al-Rāghib التشبّث, Lisān نشب, Miṣbāḥ «نشب به واستمسك», Lane ''it hung to it''), as Ibn Fāris; thick blood heads al-Khalīl, al-Jawharī, Qāmūs, Tāj — and the clot is named for clinging. (re-checked 2026-10-07)', updated_at = datetime('now')
 WHERE id = 'ASL:علق:maqayis_lugha' AND status <> 'rejected' AND statement_ar = 'العين واللام والقاف أصلٌ كبير صحيح يرجع إلى معنىً واحد، وهو أن يناط الشَّيء بالشيء العالي' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: أصل (Ibn Fāris head sentence). Primary: no shared reading (Jawharī heads with blood); Ibn Fāris gives the root sense of hanging.';
UPDATE ar_ling_root_asl SET note_md = 'Marker: first gloss. Corrected: old quote «وأصله من قولهم:» was a fragment; his only definition is the gloss of ufawwiḍu. Was: «أصله من قولهم:». Thin in this book: he glosses أُفَوِّضُ (40:44) only; then «وأصله من قولهم:» (blk_mfr_d1c13ab3efe75b25) «مالهم فَوْضَى بينهم» (blk_mfr_ed7bfe4fb54e70b0), i.e. held in common.', updated_at = datetime('now')
 WHERE id = 'ASL:فوض:raghib_mufradat' AND status <> 'rejected' AND statement_ar = 'أردّه إليه' AND is_primary = 0 AND coalesce(note_md,'') = 'Marker: first gloss. Corrected: old quote «وأصله من قولهم:» was a fragment; his only definition is the gloss of ufawwiḍu. Was: «أصله من قولهم:».';
UPDATE ar_ling_root_asl SET is_primary = 0, note_md = 'Marker: أصل (Ibn Fāris head sentence). Head continues in blk_mqy_8df8869a6a72acf0 «والالتباس به وادِّراعِه. وأصل ذلك القَرْف، وهو كلُّ قَشْر». Not primary (2026-10-07): most books head with peel / bark (القرف: القشر — al-Khalīl, al-Jawharī, Lisān, Miṣbāḥ, Qāmūs, ʿUbāb, Tāj), as al-Rāghib''s «أصل»; Ibn Fāris''s mixing is his own, and even he says «وأصل ذلك القَرْف، وهو كلُّ قَشْر» (blk_mqy_8df8869a6a72acf0).', updated_at = datetime('now')
 WHERE id = 'ASL:قرف:maqayis_lugha' AND status <> 'rejected' AND statement_ar = 'القاف والراء والفاء أصلٌ صحيح يدلُّ على مخالطةِ الشيء' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: أصل (Ibn Fāris head sentence). Primary: readings differ (mixing vs peeling); Ibn Fāris is earlier';
UPDATE ar_ling_root_asl SET is_primary = 1, note_md = 'Marker: أصل. Primary: most books head with peel / bark (القرف: القشر — al-Khalīl, al-Jawharī, Lisān, Miṣbāḥ, Qāmūs, ʿUbāb, Tāj), as al-Rāghib''s «أصل»; Ibn Fāris''s mixing is his own, and even he says «وأصل ذلك القَرْف، وهو كلُّ قَشْر» (blk_mqy_8df8869a6a72acf0). (moved from ASL:قرف:maqayis_lugha on 2026-10-07)', updated_at = datetime('now')
 WHERE id = 'ASL:قرف:raghib_mufradat' AND status <> 'rejected' AND statement_ar = 'أصل القَرْفِ والِاقْتِرَافِ: قشر اللّحاء عن الشّجر، والجلدة عن الجرح' AND is_primary = 0 AND coalesce(note_md,'') = 'Marker: أصل.';
UPDATE ar_ling_root_asl SET note_md = 'Marker: head sense. Corrected: current quote ''uprooted from its base'' is a phrase, not the root meaning. Was: «أصلها، فانْقَعَرَتْ». Primary: Both give depth/going down; al-Jawharī is earlier and plain. Print slip: read «وغيرها» — Lisān «وقعر البئر وغيرها: عمقها» (blk_lsn_a9c0ea341ae40688, p2692), Tāj (blk_taj_e344670f23592b83, p452).', updated_at = datetime('now')
 WHERE id = 'ASL:قعر:jawhari_sihah' AND status <> 'rejected' AND statement_ar = 'قعر البئر وغيزها: عمقها.' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: head sense. Corrected: current quote ''uprooted from its base'' is a phrase, not the root meaning. Was: «أصلها، فانْقَعَرَتْ». Primary: Both give depth/going down; al-Jawharī is earlier and plain.';
UPDATE ar_ling_root_asl SET statement_ar = 'وقست الشئ بغيره وعلى غيره، أقيسُهُ قَيْساً وقِياساً فانْقاسَ، إذا قدَّرتَه على مثاله. وفيه لغة أخرى قسته أقوسه قوسا', statement_en = 'to measure a thing against its like; also qāsa, yaqūsu', block_id = 'blk_sih_b3889915ae339536', page_ref = 1916, note_md = 'Marker: head word. Corrected: current quote is the form history of qisiyy; head word has no gloss, weak row. Was: «أصل قسى قؤوس، لانه فعول، إلا أنهم قدموا اللام وصيروه قسو على فلوع، ثم قلبوا الوا». Strengthened 2026-10-07: Thin head: the bow (القوس) is only named, with its gender and plurals, never glossed; his fullest gloss in the entry is measuring, with the wāw form «أقوسه قوسا» (as Ibn Fāris''s aṣl; Lane opens قوس with قاس). Was: «القَوْسُ يذكَّر ويؤنَّث».', updated_at = datetime('now')
 WHERE id = 'ASL:قوس:jawhari_sihah' AND status <> 'rejected' AND statement_ar = 'القَوْسُ يذكَّر ويؤنَّث' AND is_primary = 0 AND coalesce(note_md,'') = 'Marker: head word. Corrected: current quote is the form history of qisiyy; head word has no gloss, weak row. Was: «أصل قسى قؤوس، لانه فعول، إلا أنهم قدموا اللام وصيروه قسو على فلوع، ثم قلبوا الوا».';
UPDATE ar_ling_root_asl SET note_md = 'Marker: opening. Corrected: current quote is the origin of lubāna (need) only. Was: «أصلها الحاجة إلى اللّبن، ثم استعمل في كلّ حاجة، وأمّا اللَّبِنُ الذي يبنى به فلي». Thin in this book: milk is named with its plural and two verses; the rest are derived forms (لابن، ألبن) glossed by milk itself.', updated_at = datetime('now')
 WHERE id = 'ASL:لبن:raghib_mufradat' AND status <> 'rejected' AND statement_ar = 'اللَّبَنُ جمعه: أَلْبَانٌ' AND is_primary = 0 AND coalesce(note_md,'') = 'Marker: opening. Corrected: current quote is the origin of lubāna (need) only. Was: «أصلها الحاجة إلى اللّبن، ثم استعمل في كلّ حاجة، وأمّا اللَّبِنُ الذي يبنى به فلي».';
UPDATE ar_ling_root_asl SET is_primary = 1, note_md = 'Marker: أصل (Ibn Fāris head sentence). Primary: most books head with the meadow where beasts are let loose to roam, and read مرج البحرين as ''let them loose'' (al-Khalīl, al-Jawharī, Lisān, Miṣbāḥ, Qāmūs, Tāj, Lane); Ibn Fāris''s coming-and-going states that reading and ties المرج to it. Mixing (al-Rāghib, Ibn Durayd) is the minority. (moved from ASL:مرج:raghib_mufradat on 2026-10-07)', updated_at = datetime('now')
 WHERE id = 'ASL:مرج:maqayis_lugha' AND status <> 'rejected' AND statement_ar = 'الميم والراء والجيم أصلٌ صحيح يدلُّ على مجيءٍ وذَهابٍ واضطراب' AND is_primary = 0 AND coalesce(note_md,'') = 'Marker: أصل (Ibn Fāris head sentence).';
UPDATE ar_ling_root_asl SET is_primary = 0, note_md = 'Marker: أصل. Not primary (2026-10-07): most books head with the meadow where beasts are let loose to roam, and read مرج البحرين as ''let them loose'' (al-Khalīl, al-Jawharī, Lisān, Miṣbāḥ, Qāmūs, Tāj, Lane); Ibn Fāris''s coming-and-going states that reading and ties المرج to it. Mixing (al-Rāghib, Ibn Durayd) is the minority.', updated_at = datetime('now')
 WHERE id = 'ASL:مرج:raghib_mufradat' AND status <> 'rejected' AND statement_ar = 'أصل المَرْج: الخلط، والمرج الاختلاط' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: أصل. Primary: Mixing fits the Qurʾānic forms (marīj, mārij, maraja); Ibn Fāris''s ''unrest'' is narrower.';
UPDATE ar_ling_root_asl SET note_md = 'Marker: أصل (Ibn Fāris head sentence). Primary: most books put intercourse first and the contract second (al-Khalīl, Ibn Durayd, al-Jawharī, Tāj «الوطء في الأصل»), as Ibn Fāris; contract-first is al-Rāghib''s alone. (re-checked 2026-10-07)', updated_at = datetime('now')
 WHERE id = 'ASL:نكح:maqayis_lugha' AND status <> 'rejected' AND statement_ar = 'النون والكاف والحاء أصلٌ واحد، وهو البِضاع' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: أصل (Ibn Fāris head sentence). Primary: Only two rows and they differ (union vs contract); Ibn Fāris is earlier and plain.';
UPDATE ar_ling_root_asl SET note_md = 'Marker: أصلان. Primary: Only row. The two aṣls are named in the next blocks: blk_mqy_d2d3b9fe6fc4bd09 «الأوَّل النَّهْج، الطّريق» and blk_mqy_0ec809fe70af7475 «والآخر الانقطاع».', updated_at = datetime('now')
 WHERE id = 'ASL:نهج:maqayis_lugha' AND status <> 'rejected' AND statement_ar = 'النون والهاء والجيم أصلانِ متباينان:' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: أصلان. Primary: Only row.';
UPDATE ar_ling_root_asl SET is_primary = 0, note_md = 'Marker: أصل (Ibn Fāris head sentence). Not primary (2026-10-07): most books head with forbidding, «خلاف الأمر» (al-Khalīl, Ibn Durayd, al-Jawharī, Lisān, Miṣbāḥ, Tāj, Lane), as al-Rāghib''s row; Ibn Fāris''s ''end, reaching'' is a second sense in the others (النهاية).', updated_at = datetime('now')
 WHERE id = 'ASL:نهي:maqayis_lugha' AND status <> 'rejected' AND statement_ar = 'النون والهاء والياء أصلٌ صحيح يدلُّ على غايةٍ وبلوغ' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: أصل (Ibn Fāris head sentence). Primary: Ibn Fāris''s ''end and reaching'' covers al-Rāghib''s forbidding; earlier and clearest.';
UPDATE ar_ling_root_asl SET is_primary = 1, note_md = 'Marker: opening definition. Corrected: current quote is the origin of the word الإنهاء only. Was: «أصل: إبلاغ النهي، ثم صار متعارفا في كلّ إبلاغ، فقيل: أنهيت إلى فلان خبر كذا». Primary: most books head with forbidding, «خلاف الأمر» (al-Khalīl, Ibn Durayd, al-Jawharī, Lisān, Miṣbāḥ, Tāj, Lane), as al-Rāghib''s row; Ibn Fāris''s ''end, reaching'' is a second sense in the others (النهاية). (moved from ASL:نهي:maqayis_lugha on 2026-10-07)', updated_at = datetime('now')
 WHERE id = 'ASL:نهي:raghib_mufradat' AND status <> 'rejected' AND statement_ar = 'النهي: الزّجر عن الشيء.' AND is_primary = 0 AND coalesce(note_md,'') = 'Marker: opening definition. Corrected: current quote is the origin of the word الإنهاء only. Was: «أصل: إبلاغ النهي، ثم صار متعارفا في كلّ إبلاغ، فقيل: أنهيت إلى فلان خبر كذا».';
UPDATE ar_ling_root_asl SET statement_ar = 'والنيق: أرفع موضع في الجبل، والجمع نياق', statement_en = 'nīq: the highest place on a mountain', block_id = 'blk_sih_cc92b5c650c50dc0', page_ref = 3091, note_md = 'Marker: head word. Corrected: current quote is the start of an anecdote (Ṭarafa); Jawharī gives no definition, only the head noun with its pattern — weak row. Was: «أصله أن طرفة ابن العبد كان عند بعض الملوك». Strengthened 2026-10-07: Thin head: al-Jawharī names الناقة only by its pattern and plurals and never glosses it; the one sense he glosses for the root is height (النيق), which Ibn Fāris also files here («والأصل الواو»). Was: «الناقَةُ تقديرها فَعَلَةٌ بالتحريك، لانها جمعت على نوق».', updated_at = datetime('now')
 WHERE id = 'ASL:نوق:jawhari_sihah' AND status <> 'rejected' AND statement_ar = 'الناقَةُ تقديرها فَعَلَةٌ بالتحريك، لانها جمعت على نوق' AND is_primary = 0 AND coalesce(note_md,'') = 'Marker: head word. Corrected: current quote is the start of an anecdote (Ṭarafa); Jawharī gives no definition, only the head noun with its pattern — weak row. Was: «أصله أن طرفة ابن العبد كان عند بعض الملوك».';
UPDATE ar_ling_root_asl SET note_md = 'Marker: head sense. Corrected: old quote was a garbled fragment about plurals of mithaq; block text has print typos (ثقفة, ائمنته) copied as is. Was: «أصل، والمَياثِقُ والمَياثيقُ أيضاً». Primary: Only row. Print slip: read «ثِقَةً إذا ائتمنته» — Lisān follows this same line «وثق به يثق، بالكسر فيهما، وثاقة وثقة ائتمنه» (blk_lsn_9174cd8e9f294f93, p5040); Miṣbāḥ «أثق بكسرهما ثقة ووثوقا ائتمنته» (blk_msb_608e231d0c6bdc65, p3201).', updated_at = datetime('now')
 WHERE id = 'ASL:وثق:jawhari_sihah' AND status <> 'rejected' AND statement_ar = 'وثقت بفلان أثق بالكسر فيهما، ثقفة إذا ائمنته.' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: head sense. Corrected: old quote was a garbled fragment about plurals of mithaq; block text has print typos (ثقفة, ائمنته) copied as is. Was: «أصل، والمَياثِقُ والمَياثيقُ أيضاً». Primary: Only row.';
UPDATE ar_ling_root_asl SET note_md = 'Marker: first sense given. Corrected: old quote was form history (yady); the hand itself is never defined, power is the first sense stated. Weak row. Was: «أصلها يَدْيٌ على فَعْلٍ ساكنة العين، لأنَّ جمعها أيد ويدى». Primary: Only row (weak: hand not defined, power is first sense). Thin in this book: the hand itself is never glossed; besides power he gives only «واليَدُ: النعمة والإحسان تصطنعه» (blk_sih_efa56a766c61fdd0).', updated_at = datetime('now')
 WHERE id = 'ASL:يدي:jawhari_sihah' AND status <> 'rejected' AND statement_ar = 'واليدُ: القوَّةُ … ومالى بفلان يدان، أي طاقةٌ' AND is_primary = 1 AND coalesce(note_md,'') = 'Marker: first sense given. Corrected: old quote was form history (yady); the hand itself is never defined, power is the first sense stated. Weak row. Was: «أصلها يَدْيٌ على فَعْلٍ ساكنة العين، لأنَّ جمعها أيد ويدى». Primary: Only row (weak: hand not defined, power is first sense).';

